package com.poi.investment.auth;
import com.poi.investment.security.JwtService; import com.poi.investment.user.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final UserRepository users; private final JwtService jwt; private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder(); public AuthController(UserRepository users,JwtService jwt){this.users=users;this.jwt=jwt;} @PostMapping("/login") ResponseEntity<LoginResponse> login(@Valid @RequestBody LoginRequest input){AppUser u=users.findByUsername(input.username()).filter(x->encoder.matches(input.password(),x.getPasswordHash())).orElse(null);if(u==null)return ResponseEntity.status(HttpStatus.UNAUTHORIZED).build();return ResponseEntity.ok(new LoginResponse(jwt.issue(new JwtService.AppUserPrincipal(u.getUsername(),u.getRole())),u.getUsername(),u.getRole()));} @GetMapping("/me") UserInfo me(Authentication auth){AppUser u=users.findByUsername(auth.getName()).orElseThrow();return new UserInfo(u.getUsername(),u.getRole());} public record LoginRequest(@NotBlank String username,@NotBlank String password){} public record LoginResponse(String accessToken,String username,String role){} public record UserInfo(String username,String role){} }
